CREATE OR REPLACE FUNCTION public.can_view_quality_postings() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS (SELECT 1 FROM public.employees e WHERE lower(e.email)=lower(public.current_user_email()) AND lower(e.status)='active' AND NOT coalesce(e.disabled,false)) AND (public.user_has_permission('Quality Control') OR public.can_manage_system_red_flags()); $$;
CREATE TABLE public.quality_analysis_postings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_key text NOT NULL UNIQUE, subject text NOT NULL, sender_name text, sender_email text, received_at timestamptz NOT NULL, filename text NOT NULL, mime_type text NOT NULL, storage_path text NOT NULL, form_number text, supplier_name text, batch_number text, analysis_date text, recognition_reason text, status text NOT NULL DEFAULT 'pending', review_notes text, reviewed_by uuid, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.quality_analysis_postings TO authenticated; GRANT ALL ON public.quality_analysis_postings TO service_role;
ALTER TABLE public.quality_analysis_postings ENABLE ROW LEVEL SECURITY;
CREATE POLICY quality_postings_read ON public.quality_analysis_postings FOR SELECT TO authenticated USING (public.can_view_quality_postings());
CREATE TABLE public.quality_outlook_sync_state (id text PRIMARY KEY DEFAULT 'outlook', cursor_path text, attachment_cursor integer NOT NULL DEFAULT 0, lease_token uuid, lease_until timestamptz, paused boolean NOT NULL DEFAULT false, pause_reason text, last_run_at timestamptz, last_success_at timestamptz, last_error text, checked_attachments bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.quality_outlook_sync_state TO service_role;
ALTER TABLE public.quality_outlook_sync_state ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.quality_outlook_checked_items (source_key text PRIMARY KEY, outcome text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.quality_outlook_checked_items TO service_role;
ALTER TABLE public.quality_outlook_checked_items ENABLE ROW LEVEL SECURITY;
INSERT INTO public.quality_outlook_sync_state(id) VALUES ('outlook');
CREATE OR REPLACE FUNCTION public.acquire_quality_outlook_lease(p_token uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.quality_outlook_sync_state; BEGIN UPDATE public.quality_outlook_sync_state SET lease_token=p_token, lease_until=now()+interval '10 minutes',last_run_at=now(),updated_at=now() WHERE id='outlook' AND NOT paused AND (lease_until IS NULL OR lease_until<now()) RETURNING * INTO s; IF NOT FOUND THEN RETURN NULL; END IF; RETURN to_jsonb(s); END; $$;
REVOKE ALL ON FUNCTION public.acquire_quality_outlook_lease(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.acquire_quality_outlook_lease(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.quality_outlook_status() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_view_quality_postings() THEN RAISE EXCEPTION 'Quality access required'; END IF; RETURN (SELECT jsonb_build_object('paused',paused,'pause_reason',pause_reason,'last_success_at',last_success_at,'last_error',last_error,'checked_attachments',checked_attachments,'running',lease_until>now()) FROM public.quality_outlook_sync_state WHERE id='outlook'); END; $$;
REVOKE ALL ON FUNCTION public.quality_outlook_status() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.quality_outlook_status() TO authenticated;
CREATE OR REPLACE FUNCTION public.review_quality_posting(p_id uuid,p_status text,p_notes text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_manage_system_red_flags() THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF p_status NOT IN ('reviewed','needs_correction','pending') THEN RAISE EXCEPTION 'Invalid review status'; END IF; IF length(coalesce(p_notes,''))>4000 THEN RAISE EXCEPTION 'Review note is too long'; END IF; UPDATE public.quality_analysis_postings SET status=p_status,review_notes=p_notes,reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() WHERE id=p_id; IF NOT FOUND THEN RAISE EXCEPTION 'Posting not found'; END IF; RETURN jsonb_build_object('ok',true); END; $$;
REVOKE ALL ON FUNCTION public.review_quality_posting(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.review_quality_posting(uuid,text,text) TO authenticated;
CREATE POLICY quality_outlook_files_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id='quality-outlook-postings' AND public.can_view_quality_postings());
CREATE OR REPLACE FUNCTION public.quality_postings_touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE TRIGGER quality_postings_updated BEFORE UPDATE ON public.quality_analysis_postings FOR EACH ROW EXECUTE FUNCTION public.quality_postings_touch_updated_at();
CREATE TRIGGER quality_outlook_state_updated BEFORE UPDATE ON public.quality_outlook_sync_state FOR EACH ROW EXECUTE FUNCTION public.quality_postings_touch_updated_at();
CREATE TRIGGER quality_outlook_items_updated BEFORE UPDATE ON public.quality_outlook_checked_items FOR EACH ROW EXECUTE FUNCTION public.quality_postings_touch_updated_at();